input.content:
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  color: #1f2937;
  background: #f3f4f6;
}

[hidden] {
  display: none !important;
}

header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 24px;
  padding: 12px 20px;
  background: #1f2937;
  color: #fff;
}

header h1 {
  margin: 0;
  font-size: 1.25rem;
}

nav a {
  margin-right: 12px;
  padding: 4px 0;
  color: #cbd5e1;
  text-decoration: none;
}

nav a.active {
  color: #fff;
  border-bottom: 2px solid #60a5fa;
}

main {
  max-width: 960px;
  margin: 0 auto;
  padding: 20px;
}

.view {
  padding: 16px 20px;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}

.form,
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
  margin-bottom: 16px;
}

label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.85rem;
  color: #4b5563;
}

